    const prev = all || !log.length ? null : (cur > 0 ? log[cur - 1].code : r.ir);
    const now = new Map(snap.map(c => [c.id, c])), was = prev ? new Set(prev.map(c => c.id)) : null;
    const hit = !all && log[cur] ? new Set(log[cur].ids) : new Set();
    const blocks = (code, f) => TC.basicBlocks(code).map(b => ({ name: b.name, succ: b.succ.length ? '→ ' + b.succ.join(', ') : 'end', lines: code.slice(b.start, b.end + 1).map(f) }));
    const before = blocks(r.ir, c => {
      const k = now.get(c.id), gone = !k, fresh = gone && was && was.has(c.id), changed = k && TC.tacText(k) !== TC.tacText(c);
      return { text: TC.tacText(c), deco: gone ? 'line-through 1.5px' : 'none', color: gone ? 'var(--ink3)' : c.op === 'LABEL' ? 'var(--hue-ink)' : 'var(--ink)', bg: fresh ? 'var(--hue-soft)' : 'transparent', newText: changed ? '→ ' + TC.tacText(k) : '', pad: c.op === 'LABEL' ? '10px' : '26px' };
    });
    const after = blocks(snap, c => ({ text: TC.tacText(c), color: c.op === 'LABEL' ? 'var(--hue-ink)' : 'var(--ink)', bg: hit.has(c.id) ? 'var(--hue-soft)' : 'transparent', pad: c.op === 'LABEL' ? '10px' : '26px' }));
    const rows = log.map((l, k) => { const on = !all && k === cur; return { k: k + 1, rule: l.rule, name: TC.OPT_RULES[l.rule], line: l.line, msg: l.msg, bg: on ? 'var(--hue-soft)' : 'var(--surface)', ring: on ? '0 0 0 2px var(--hue)' : 'none', op: !all && k > cur ? 0.35 : 1 }; });
    const sameTxt = st.limitHit ? 'Not checked' : st.same ? '✓ Yes' : '✕ No';
    const l = log[cur];
    const caption = all ? (log.length ? `${TCV.plural(log.length, 'change')} over ${TCV.plural(O.rounds, 'round')}: ${st.before} → ${st.after} instructions and ${st.stepsBefore} → ${st.stepsAfter} machine steps.${st.same ? ' The drawing is exactly the same.' : ''}` : 'Nothing to change: every instruction is already needed.') : `${l.rule} ${TC.OPT_RULES[l.rule]} · line ${l.line}: ${l.msg}`;
